using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Ada", 37), personInfo);
Person p = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {p}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"TryGetTypeInfo succeeded for {info!.Type.Name}");

// Use a type that has NO resolver registered (empty chain resolver)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => { if (ti.Type == typeof(int)) throw new InvalidOperationException(); } }
    }
};
// For a truly "missing" type, use an empty resolver:
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // resolves nothing
};

if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing))
    Console.WriteLine("Found metadata (unexpected)");
else
    Console.WriteLine("TryGetTypeInfo returned false — no metadata, no exception");

record Person(string Name, int Age);

